/**
 * frontend/src/Enrollment.jsx - VERSION FINALE INTÉGRALE
 * ✅ Synchronisé avec le backend corrigé
 * ✅ Styles complets inclus
 */

import React, { useState } from 'react';
import { studentsAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const Enrollment = ({ onSuccess }) => {
  const [formData, setFormData] = useState({ name: '', email: '' });
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState(null);
  const [messageType, setMessageType] = useState('info');

  const showMessage = (msg, type) => {
    setMessage(msg);
    setMessageType(type);
    if (type === 'success' || type === 'error') {
      setTimeout(() => setMessage(null), 6000);
    }
  };

  const handleFileSelect = (e) => {
    const selectedFile = e.target.files[0];
    if (!selectedFile) return;
    setFile(selectedFile);
    const reader = new FileReader();
    reader.onload = (event) => setPreview(event.target.result);
    reader.readAsDataURL(selectedFile);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.name.trim() || !file) {
      showMessage('❌ Le nom et la photo sont requis', 'error');
      return;
    }

    setLoading(true);
    try {
      // Conversion fichier -> Base64
      const fileContent = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      showMessage('⏳ Analyse de l\'image et enrôlement...', 'info');

      const response = await studentsAPI.enrollFromImage(
        formData.name, 
        formData.email || null, 
        fileContent
      );

      if (response.data.success) {
        showMessage(`✅ Enrôlement réussi pour ${response.data.name} !`, 'success');
        setFormData({ name: '', email: '' });
        setFile(null);
        setPreview(null);
        if (onSuccess) onSuccess();
      }
    } catch (error) {
      // ✅ Lecture de l'erreur structurée du backend
      const errorMsg = error.response?.data?.error || error.response?.data?.message || "Erreur serveur";
      showMessage(`❌ ${errorMsg}`, 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>➕ Enrôler un Étudiant</h2>
        <p style={styles.subtitle}>Enregistrez un nouveau visage dans la base biométrique</p>

        {message && (
          <div style={{
            ...styles.message,
            backgroundColor: { success: '#DCFCE7', error: '#FEE2E2', info: '#DBEAFE' }[messageType],
            color: { success: '#166534', error: '#991B1B', info: '#0C4A6E' }[messageType]
          }}>
            {message}
          </div>
        )}

        <form onSubmit={handleSubmit} style={styles.form}>
          <div style={styles.formGroup}>
            <label style={styles.label}>👤 Nom complet *</label>
            <input
              type="text"
              name="name"
              value={formData.name}
              onChange={(e) => setFormData({...formData, name: e.target.value})}
              placeholder="Ex: Ahmed Hassan"
              style={styles.input}
              disabled={loading}
            />
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>📧 Email (optionnel)</label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={(e) => setFormData({...formData, email: e.target.value})}
              placeholder="ahmed@example.com"
              style={styles.input}
              disabled={loading}
            />
          </div>

          <div style={styles.formGroup}>
            <label style={styles.label}>📸 Photo du visage *</label>
            <div style={styles.uploadArea}>
              <input
                type="file"
                accept="image/*"
                onChange={handleFileSelect}
                style={styles.fileInput}
                id="imageInput"
              />
              <label htmlFor="imageInput" style={styles.uploadLabel}>
                {preview ? (
                  <img src={preview} alt="Preview" style={styles.previewImage} />
                ) : (
                  <div style={styles.uploadContent}>
                    <span style={{ fontSize: '2rem' }}>📷</span>
                    <strong>Cliquez pour choisir une photo</strong>
                  </div>
                )}
              </label>
            </div>
          </div>

          <button
            type="submit"
            disabled={loading || !file}
            style={{
              ...styles.submitBtn,
              backgroundColor: loading ? COLORS.textMuted : COLORS.primary,
              cursor: loading ? 'not-allowed' : 'pointer'
            }}
          >
            {loading ? '⏳ Traitement...' : '✅ Finaliser l\'enrôlement'}
          </button>
        </form>
      </div>
    </div>
  );
};

const styles = {
  container: { padding: '20px', maxWidth: '600px', margin: '0 auto' },
  card: { backgroundColor: COLORS.surface, borderRadius: '16px', padding: '30px', boxShadow: '0 4px 20px rgba(0,0,0,0.08)', border: `1px solid ${COLORS.border}` },
  title: { margin: '0 0 8px 0', fontSize: '1.5rem', fontWeight: 800, color: COLORS.textMain, textAlign: 'center' },
  subtitle: { margin: '0 0 24px 0', fontSize: '0.9rem', color: COLORS.textMuted, textAlign: 'center' },
  message: { padding: '12px 16px', borderRadius: '10px', marginBottom: '20px', fontSize: '0.85rem', fontWeight: 600 },
  form: { display: 'flex', flexDirection: 'column', gap: '20px' },
  formGroup: { display: 'flex', flexDirection: 'column', gap: '8px' },
  label: { fontSize: '0.9rem', fontWeight: 700, color: COLORS.textMain },
  input: { padding: '12px', borderRadius: '10px', border: `1.5px solid ${COLORS.border}`, fontSize: '1rem', outline: 'none' },
  uploadArea: { border: `2px dashed ${COLORS.border}`, borderRadius: '12px', overflow: 'hidden', position: 'relative' },
  fileInput: { display: 'none' },
  uploadLabel: { display: 'block', width: '100%', minHeight: '150px', cursor: 'pointer' },
  uploadContent: { display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '150px', color: COLORS.textMuted },
  previewImage: { width: '100%', height: '200px', objectFit: 'cover' },
  submitBtn: { padding: '14px', borderRadius: '12px', color: 'white', border: 'none', fontSize: '1rem', fontWeight: 700, transition: 'all 0.2s' }
};

export default Enrollment;
